    //         oled_write_P(PSTR("FN2"), false);
    //         break;
    //     case _FN3:
    //         oled_write_P(PSTR("FN3"), false);
    //         break;
    //     case _FN4:
    //         oled_write_P(PSTR("FN4"), false);
    //         break;            
    //     case _ADJUST:
    //         oled_write_P(PSTR("ADJ"), false);
    //         break;

    //     default:
